// TikTok Marketing API レスポンス展開
// 構造: { code, message, data: { list: [{ dimensions, metrics }], page_info } }
// 1 行 = (campaign_id, stat_time_day) × metrics
// stat_time_day は "2026-05-25 00:00:00" 形式 → YYYY-MM-DD に丸める

const now = new Date().toISOString();
const advertiserId = '7643694875730001936';
const rows = [];
const toInt = v => (v === undefined || v === null || v === '') ? null : Math.round(Number(v));
const toFloat = v => (v === undefined || v === null || v === '') ? null : Number(v);

for (const item of $input.all()) {
  const body = item.json;
  if (!body || body.code !== 0 || !body.data || !Array.isArray(body.data.list)) {
    // API エラー: code != 0 → log で気付けるよう raw 出力
    if (body && body.code !== 0) throw new Error('TikTok API error code=' + body.code + ' message=' + body.message + ' full=' + JSON.stringify(body).substring(0, 2000));
    continue;
  }
  for (const r of body.data.list) {
    const d = r.dimensions || {};
    const m = r.metrics || {};
    const dateStr = (d.stat_time_day || '').substring(0, 10);
    const campaignId = d.campaign_id ? String(d.campaign_id) : null;
    if (!dateStr || !campaignId) continue;
    rows.push({
      date:            dateStr,
      advertiser_id:   advertiserId,
      campaign_id:     campaignId,
      campaign_name:   m.campaign_name || null,
      objective_type:  m.objective_type || null,
      ad_group_id:     null,
      impressions:     toInt(m.impressions),
      clicks:          toInt(m.clicks),
      cost:            toInt(m.spend),
      conversions:     toFloat(m.conversion),
      revenue:         (m.complete_payment_roas != null && m.spend != null) ? Math.round(Number(m.complete_payment_roas) * Number(m.spend)) : null,
      video_views:     toInt(m.video_play_actions),
      video_p25_count: toInt(m.video_views_p25),
      video_p50_count: toInt(m.video_views_p50),
      video_p75_count: toInt(m.video_views_p75),
      video_p100_count:toInt(m.video_views_p100),
      inserted_at:     now
    });
  }
}

return rows.map(json => ({ json }));
